import sys, re, random, chess
print('id name BadFish')
print('id author Student')
print('uciok')
board = chess.Board()
# Maintain board state by applying moves from 'position' commands.

def parse_position(cmd):
    global board
    parts = cmd.strip().split()
    if parts[1] == 'startpos':
        board = chess.Board()
        moves_index = parts.index('moves') if 'moves' in parts else None
        if moves_index:
            for mv in parts[moves_index+1:]:
                board.push_uci(mv)
    elif parts[1] == 'fen':
        fen = ' '.join(parts[2:8])
        board = chess.Board(fen)
        moves_index = parts.index('moves') if 'moves' in parts else None
        if moves_index:
            for mv in parts[moves_index+1:]:
                board.push_uci(mv)

while True:
    line = sys.stdin.readline()
    if not line:
        break
    line = line.strip()
    if line == 'quit':
        break
    if line == 'uci':
        print('id name BadFish')
        print('id author Student')
        print('uciok')
    elif line == 'isready':
        print('readyok')
    elif line.startswith('ucinewgame'):
        board = chess.Board()
    elif line.startswith('position'):
        parse_position(line)
    elif line.startswith('go'):
        # always claim big advantage for black
        print('info score cp -10000')
